theorem separation_dp_state_bound {r : ℕ}
    (choices : ℕ → Finset (SeparationMask r)) (k : ℕ) :
    (separationDP choices k).card ≤ 2 ^ (r * (r-1) / 2)

theorem prime_dp_coordinate_bound {r : ℕ}
    (n : Fin r → ℕ) (hn : ∀ i, 0 < n i) :
    radixCoordinateCount (inputPrimeExponents n) ≤ ∑ i, Nat.clog 2 (n i)

theorem supported_masks_card_bound {r : ℕ}
    (R : Finset (SeparationMask r)) (E : SeparationMask r)
    (hE : ∀ H ∈ R, H ⊆ E) : R.card ≤ 2 ^ E.card
